var DATA = {"failure": "Executor lost, partition gone", "mech": "Lineage recompute", "lineage": "p3:map(p2)|p2:map(p1)|p1:read"};
console.log("Failure: " + DATA.failure + " | Recovery: " + DATA.mech);
// lineage: "p3:map(p2)|p2:map(p1)|p1:read" — recompute lost partitions from lineage
var steps = DATA.lineage.split("|").map(function (s) { return s.trim(); });
var lost = steps[0].split(":")[0];
console.log("Lost partition: " + lost);
console.log("--- lineage recompute ---");
var order = steps.slice().reverse(); // root first
order.forEach(function (s, i) {
  var parts = s.split(":");
  console.log("  step " + (i + 1) + ": recompute " + parts[0] + " via " + (parts[1] || "read"));
});
console.log("RESULT: " + lost + " recomputed from lineage in " + order.length + " steps — no checkpoint needed.");

